// Cross-platform release notification contract.
//
// Update discovery remains owned by each distribution channel (Tauri updater, Android manifest,
// App Store/Google Play catalogue, or a waiting service worker). Once that channel has proved a newer
// version exists, it calls this module. The module emits at most one OS-level notification per version,
// prefers the native mobile bridge, and never asks a browser for notification permission implicitly.

export interface ReleaseNotificationPayload {
  version: string;
  title: string;
  body: string;
  actionUrl?: string;
}

export interface ReleaseNotificationEnv {
  storageGet(key: string): string | null;
  storageSet(key: string, value: string): void;
  nativeNotify(payload: ReleaseNotificationPayload): Promise<boolean>;
  browserNotify(payload: ReleaseNotificationPayload): Promise<boolean>;
}

const RELEASE_NOTICE_PREFIX = "gc.release-notification.v1.";
const inFlight = new Set<string>();

function normalizedPayload(payload: ReleaseNotificationPayload): ReleaseNotificationPayload | null {
  const version = String(payload.version ?? "").trim();
  const title = String(payload.title ?? "").trim();
  const body = String(payload.body ?? "").trim();
  if (!version || !title || !body) return null;
  const actionUrl = typeof payload.actionUrl === "string" && payload.actionUrl.trim()
    ? payload.actionUrl.trim()
    : undefined;
  return { version, title, body, ...(actionUrl ? { actionUrl } : {}) };
}

function storageKey(version: string): string {
  return `${RELEASE_NOTICE_PREFIX}${encodeURIComponent(version)}`;
}

/**
 * Emit a native/browser release notification once per version. Failed or unavailable delivery does not
 * burn the dedupe key: the next lifecycle check may try again after the user grants OS permission.
 */
export async function notifyReleaseAvailable(
  payload: ReleaseNotificationPayload,
  env: ReleaseNotificationEnv = browserReleaseNotificationEnv(),
): Promise<boolean> {
  const normalized = normalizedPayload(payload);
  if (!normalized) return false;
  const key = storageKey(normalized.version);
  if (inFlight.has(key) || env.storageGet(key) === "1") return false;

  inFlight.add(key);
  let shown = false;
  try {
    shown = await env.nativeNotify(normalized);
    if (!shown) shown = await env.browserNotify(normalized);
    if (shown) env.storageSet(key, "1");
    return shown;
  } catch {
    return false;
  } finally {
    inFlight.delete(key);
  }
}

export function browserReleaseNotificationEnv(): ReleaseNotificationEnv {
  const safeStorageGet = (key: string): string | null => {
    try {
      return typeof localStorage !== "undefined" ? localStorage.getItem(key) : null;
    } catch {
      return null;
    }
  };
  const safeStorageSet = (key: string, value: string): void => {
    try {
      if (typeof localStorage !== "undefined") localStorage.setItem(key, value);
    } catch {
      /* private mode/quota: process-local collapse still prevents concurrent duplicates */
    }
  };

  return {
    storageGet: safeStorageGet,
    storageSet: safeStorageSet,
    nativeNotify: async (payload) => {
      const bridge = (globalThis as typeof globalThis & {
        __gcNotifyReleaseAvailable?: (notice: ReleaseNotificationPayload) => Promise<boolean | void>;
      }).__gcNotifyReleaseAvailable;
      if (typeof bridge !== "function") return false;
      return (await bridge(payload)) !== false;
    },
    browserNotify: async (payload) => {
      if (typeof Notification === "undefined" || Notification.permission !== "granted") return false;
      const target = payload.actionUrl ?? "/?app=1#/settings";
      const options: NotificationOptions = {
        body: payload.body,
        tag: `greenchat-release-${payload.version}`,
        data: { kind: "update", version: payload.version, action_url: target },
      };

      try {
        if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
          const registration = await navigator.serviceWorker.getRegistration();
          if (registration && typeof registration.showNotification === "function") {
            await registration.showNotification(payload.title, options);
            return true;
          }
        }
      } catch {
        /* fall through to the page-owned Notification API */
      }

      try {
        const notice = new Notification(payload.title, options);
        notice.onclick = () => {
          try {
            globalThis.focus?.();
            if (typeof location !== "undefined") location.href = target;
          } catch {
            /* notification already served its purpose */
          }
          notice.close();
        };
        return true;
      } catch {
        return false;
      }
    },
  };
}
