import type { AuthLossContext } from "../../core/src/api.ts";

export interface AccountAuthLossDeps {
  activeAccountId(): number | null;
  logout(): Promise<void>;
}

/**
 * Coalesce a fatal auth verdict for the account that actually started the failed operation.
 * A missing active account means an intentional add-account boundary; a different id means the
 * callback came from the previous account after the user already switched. Both are ignored.
 */
export function createAccountAuthLossHandler(deps: AccountAuthLossDeps) {
  let inFlight: Promise<void> | null = null;
  return (context?: AuthLossContext): Promise<void> => {
    const active = deps.activeAccountId();
    if (!Number.isSafeInteger(active) || active === null || active <= 0) return Promise.resolve();
    if (!Number.isSafeInteger(context) || Number(context) !== active) return Promise.resolve();
    if (inFlight) return inFlight;
    const task = deps.logout().finally(() => {
      if (inFlight === task) inFlight = null;
    });
    inFlight = task;
    return task;
  };
}
