import type { I18n } from "./i18n.ts";
import { createFocusTrap } from "./a11y.ts";
import { clear, el, modalRoot } from "./dom.ts";
import { icon } from "./icons.ts";
import type { ManualUpdateResult } from "./manual_update_check.ts";

export interface ManualUpdateResultView {
  root: HTMLElement;
  showChecking(): void;
  showResult(result: ManualUpdateResult): void;
  destroy(): void;
}

export interface ManualUpdateResultDeps {
  i18n: I18n;
  fallback: HTMLElement;
}

/**
 * A single modal owns the whole manual-check lifecycle. Keeping one surface avoids the old behaviour
 * where the button wrote a short status line at the top of Settings and the result was easy to miss.
 */
export function createManualUpdateResultView(deps: ManualUpdateResultDeps): ManualUpdateResultView {
  const { i18n } = deps;
  const symbol = el("div", { class: "gc-manual-update-symbol", "aria-hidden": "true" });
  const title = el("h2", { class: "gc-manual-update-title" });
  const actions = el("div", { class: "gc-manual-update-actions" });
  const close = el("button", {
    type: "button",
    class: "gc-icon-btn gc-manual-update-close",
    title: i18n.t("common.close"),
    "aria-label": i18n.t("common.close"),
  }, [icon("close")]);
  const card = el("section", { class: "gc-manual-update-card" }, [close, symbol, title, actions]);
  const root = el("div", {
    class: "gc-manual-update-layer",
    role: "dialog",
    "aria-modal": "true",
    "aria-live": "polite",
    "aria-atomic": "true",
    "aria-label": i18n.t("settings.checkUpdates"),
  }, [card]);
  const host = modalRoot(deps.fallback);
  host.append(root);
  const trap = createFocusTrap(root);
  let destroyed = false;

  const setSymbol = (state: "checking" | "latest" | "available" | "unknown"): void => {
    clear(symbol);
    symbol.classList.remove("is-checking", "is-latest", "is-available", "is-unknown", "is-pending");
    symbol.classList.add(state === "unknown" ? "is-pending" : `is-${state}`);
    if (state === "checking") {
      symbol.append(el("span", { class: "gc-manual-update-spinner" }), el("span", { class: "gc-manual-update-pulse" }));
    } else if (state === "latest") {
      symbol.append(el("span", { class: "gc-manual-update-check" }));
    } else if (state === "available") {
      symbol.append(el("span", { class: "gc-manual-update-cross" }));
    } else {
      const wait = icon("clock", "gc-manual-update-wait");
      wait.setAttribute("width", "66");
      wait.setAttribute("height", "66");
      wait.setAttribute("stroke-width", "1.6");
      symbol.append(wait);
    }
  };

  const showChecking = (): void => {
    if (destroyed) return;
    card.dataset.state = "checking";
    setSymbol("checking");
    title.textContent = i18n.t("settings.checkingUpdates");
    clear(actions);
  };

  const showResult = (result: ManualUpdateResult): void => {
    if (destroyed) return;
    card.dataset.state = result.state;
    setSymbol(result.state);
    clear(actions);
    if (result.state === "latest") {
      title.textContent = i18n.t("settings.updateLatest");
      return;
    }
    if (result.state === "unknown") {
      title.textContent = i18n.t("settings.updateCheckUnavailable");
      return;
    }
    title.textContent = i18n.t("settings.updateAvailable", { version: result.version ?? "" });
    const update = el("button", {
      type: "button",
      class: "gc-btn gc-btn-accent gc-manual-update-action",
    }, [i18n.t("update.action")]);
    update.addEventListener("click", () => {
      update.setAttribute("disabled", "");
      try {
        result.activate?.();
      } finally {
        destroy();
      }
    });
    actions.append(update);
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    destroy();
  };
  root.addEventListener("keydown", onKeyDown);
  close.addEventListener("click", () => destroy());

  const destroy = (): void => {
    if (destroyed) return;
    destroyed = true;
    trap.release();
    root.removeEventListener("keydown", onKeyDown);
    root.remove();
  };

  showChecking();
  trap.activate();
  return { root, showChecking, showResult, destroy };
}
