// Privacy-preserving functional incident bridge.
//
// JavaScript crashes are only one class of product failure. A call can time out, the realtime socket can
// reconnect forever, an API can repeatedly fail or a background worker can stop making progress without
// throwing an uncaught exception. This module turns those *semantic* failures into ordinary redacted
// diagnostics reports so the existing /v1/client/crash pipeline and scripts/crashes.mjs can group them.
//
// Privacy contract: this reporter is STRICTLY covered by the existing diagnostics opt-in. It never reads
// message/contact data, never captures DOM/screens/console output and never persists its own state. The
// context accepted here is restricted to fixed technical labels and already-redacted routes. A per-key
// in-memory cooldown prevents one broken loop from exhausting the server's five-reports/day quota.
import type { RequestObservation } from "./api.ts";
import type { Diagnostics } from "./diagnostics.ts";
import { redactBreadcrumb, redactRoute, redactText } from "./diag_redact.ts";

export const FUNCTIONAL_INCIDENT_CODES = [
  "api.network_failure",
  "api.server_failure",
  "api.slow_response",
  "background.operation_failed",
  "boot.failed",
  "call.connection_failed",
  "call.recovery_failed",
  "call.setup_timeout",
  "conference.join_failed",
  "message.outbox_failed",
  "ui.blank_screen",
  "ws.reconnect_stalled",
] as const;

export type FunctionalIncidentCode = (typeof FUNCTIONAL_INCIDENT_CODES)[number];

export interface FunctionalIncidentInput {
  code: FunctionalIncidentCode;
  /** Fixed technical dimensions only. Values are redacted/capped before use. */
  dimensions?: Readonly<Record<string, string | number | boolean | null | undefined>>;
  /** Extra route/screen-style breadcrumbs. Never pass content, ids or user-entered strings. */
  breadcrumbs?: readonly string[];
}

export interface FunctionalIncidentReporter {
  report(input: FunctionalIncidentInput): Promise<boolean>;
  observeApi(observation: RequestObservation): void;
  clearCooldowns(): void;
}

export interface FunctionalIncidentReporterOptions {
  diagnostics: Pick<Diagnostics, "getConsent" | "reportError">;
  now?: () => number;
  cooldownMs?: number;
  maxCooldownKeys?: number;
  slowApiMs?: number;
  onError?: (error: unknown) => void;
}

const DEFAULT_COOLDOWN_MS = 6 * 60 * 60 * 1000;
const DEFAULT_MAX_COOLDOWN_KEYS = 96;
const DEFAULT_SLOW_API_MS = 15_000;
const DIMENSION_KEY_RE = /^[a-z][a-z0-9_.-]{0,31}$/;

function fnv1a32(value: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function normalizeDimensionValue(value: string | number | boolean | null | undefined): string | null {
  if (value === undefined || value === null) return null;
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return null;
    return String(Math.round(value));
  }
  const out = redactText(value, 48).replace(/\s+/g, "_");
  return out === "" ? null : out;
}

function normalizedDimensions(
  dimensions: FunctionalIncidentInput["dimensions"],
): Array<[string, string]> {
  if (!dimensions) return [];
  const entries: Array<[string, string]> = [];
  for (const [rawKey, rawValue] of Object.entries(dimensions)) {
    const key = rawKey.toLowerCase();
    if (!DIMENSION_KEY_RE.test(key)) continue;
    const value = normalizeDimensionValue(rawValue);
    if (value === null) continue;
    entries.push([key, value]);
  }
  entries.sort(([a], [b]) => a.localeCompare(b));
  return entries.slice(0, 8);
}

function statusFamily(status: number): string {
  if (status === 0) return "network";
  if (status >= 500) return "5xx";
  if (status >= 400) return "4xx";
  if (status >= 300) return "3xx";
  return "2xx";
}

export function createFunctionalIncidentReporter(
  opts: FunctionalIncidentReporterOptions,
): FunctionalIncidentReporter {
  const now = opts.now ?? (() => Date.now());
  const cooldownMs = Math.max(0, opts.cooldownMs ?? DEFAULT_COOLDOWN_MS);
  const maxCooldownKeys = Math.max(8, opts.maxCooldownKeys ?? DEFAULT_MAX_COOLDOWN_KEYS);
  const slowApiMs = Math.max(1_000, opts.slowApiMs ?? DEFAULT_SLOW_API_MS);
  const onError = opts.onError ?? (() => undefined);
  const lastSent = new Map<string, number>();

  function remember(key: string, at: number): void {
    lastSent.delete(key);
    lastSent.set(key, at);
    while (lastSent.size > maxCooldownKeys) {
      const oldest = lastSent.keys().next().value as string | undefined;
      if (oldest === undefined) break;
      lastSent.delete(oldest);
    }
  }

  async function report(input: FunctionalIncidentInput): Promise<boolean> {
    try {
      const dimensions = normalizedDimensions(input.dimensions);
      const material = [input.code, ...dimensions.map(([key, value]) => `${key}=${value}`)].join("|");
      const fingerprint = fnv1a32(material);
      const cooldownKey = `${input.code}:${fingerprint}`;
      const at = now();
      const previous = lastSent.get(cooldownKey);
      if (previous !== undefined && at - previous < cooldownMs) return false;
      if (!(await opts.diagnostics.getConsent())) return false;

      // Reserve before the await so concurrent failures collapse into one report. reportError itself is
      // best-effort and queues locally on network loss, therefore a successful call means the evidence is
      // retained or delivered without this layer having to duplicate its persistence contract.
      remember(cooldownKey, at);
      const dimensionText = dimensions.map(([key, value]) => `${key}=${value}`).join(" ");
      const header = `FunctionalIncident: ${input.code} fp=${fingerprint}${dimensionText ? ` ${dimensionText}` : ""}`;
      const breadcrumbs = [
        `incident:${input.code}`,
        ...dimensions.map(([key, value]) => `${key}:${value}`),
        ...(input.breadcrumbs ?? []),
      ].map(redactBreadcrumb).filter(Boolean).slice(-20);
      await opts.diagnostics.reportError({
        message: header,
        stack: `${header}\n    at functional_incidents.ts:1:1`,
        breadcrumbs,
      });
      return true;
    } catch (error) {
      onError(error);
      return false;
    }
  }

  function observeApi(observation: RequestObservation): void {
    try {
      const route = redactRoute(observation.path);
      // Never diagnose delivery of diagnostics itself: an offline /v1/client/crash request must not
      // recursively create another /v1/client/crash request. Session/aggregate endpoints share the gate.
      if (/^\/v1\/client\/(?:crash|diag|sessions)(?:\/|$)/.test(route)) return;
      const common = {
        method: observation.method,
        route: fnv1a32(route),
        status: statusFamily(observation.status),
      } as const;
      if (observation.status === 0) {
        // A caller-owned AbortSignal is also surfaced as NETWORK. Ignore very fast cancellations (view
        // unmount/account switch) and retain real timeouts or sustained no-response failures.
        if (observation.code === "TIMEOUT" || observation.ms >= 5_000) {
          void report({ code: "api.network_failure", dimensions: common, breadcrumbs: [route] });
        }
        return;
      }
      if (observation.status >= 500) {
        void report({
          code: "api.server_failure",
          dimensions: { ...common, error: observation.code ?? "unknown" },
          breadcrumbs: [route],
        });
        return;
      }
      if (observation.ok && observation.ms >= slowApiMs) {
        const bucket = observation.ms >= 60_000 ? "60s_plus" : observation.ms >= 30_000 ? "30s_plus" : "15s_plus";
        void report({ code: "api.slow_response", dimensions: { ...common, bucket }, breadcrumbs: [route] });
      }
    } catch (error) {
      onError(error);
    }
  }

  return {
    report,
    observeApi,
    clearCooldowns(): void { lastSent.clear(); },
  };
}
