export interface BadgeRefreshDeps {
  allowed(): boolean;
  loadCount(): Promise<number>;
  apply(count: number): void;
  setTimer?(fn: () => void, ms: number): unknown;
  clearTimer?(handle: unknown): void;
  delayMs?: number;
}

export interface BadgeRefreshController {
  request(): void;
  reset(): void;
}

/**
 * Debounce unread refreshes and keep at most one HTTP request in flight.
 *
 * Event replay can deliver thousands of historical message frames in seconds. A timer-only debounce
 * still allows another timer to start while the previous GET is pending, which turned that replay
 * into a /v1/badge storm. Requests arriving during a flight now collapse into one trailing refresh;
 * the stale flight is not allowed to paint over the newer intent.
 */
export function createBadgeRefreshController(deps: BadgeRefreshDeps): BadgeRefreshController {
  const setTimer = deps.setTimer ?? ((fn: () => void, ms: number): unknown => setTimeout(fn, ms));
  const clearTimer = deps.clearTimer ?? ((handle: unknown): void => clearTimeout(handle as ReturnType<typeof setTimeout>));
  const delayMs = deps.delayMs ?? 800;
  let timer: unknown = null;
  let inFlight = false;
  let trailing = false;
  let epoch = 0;
  let latestRequest = 0;

  const schedule = (): void => {
    if (timer !== null || inFlight || !deps.allowed()) return;
    timer = setTimer(() => {
      timer = null;
      if (!deps.allowed()) return;
      const mineEpoch = epoch;
      const mineRequest = latestRequest;
      inFlight = true;
      void deps.loadCount()
        .then((count) => {
          if (mineEpoch === epoch && mineRequest === latestRequest && deps.allowed()) deps.apply(count);
        })
        .catch(() => undefined)
        .finally(() => {
          inFlight = false;
          if (mineEpoch !== epoch) {
            trailing = false;
            return;
          }
          if (trailing && deps.allowed()) {
            trailing = false;
            schedule();
          }
        });
    }, delayMs);
  };

  return {
    request(): void {
      if (!deps.allowed()) return;
      latestRequest += 1;
      if (inFlight) {
        trailing = true;
        return;
      }
      schedule();
    },
    reset(): void {
      epoch += 1;
      latestRequest += 1;
      trailing = false;
      if (timer !== null) clearTimer(timer);
      timer = null;
      deps.apply(0);
    },
  };
}
