import { el } from "../dom.ts";
import { createFocusTrap } from "../a11y.ts";
import { icon } from "../icons.ts";
import { avatarTone, initials } from "./message_menu.ts";
import type { ConferenceInviteNotice } from "./conference_invite_event.ts";

export type ConferenceInviteCloseReason = "accepted" | "declined" | "expired" | "replaced" | "account_changed";

export interface ConferenceInviteOverlayDeps {
  locale: string;
  notice: ConferenceInviteNotice;
  onAccept(notice: ConferenceInviteNotice): Promise<void> | void;
  onDecline?(notice: ConferenceInviteNotice): void;
  onClosed?(reason: ConferenceInviteCloseReason): void;
  now?(): number;
  setTimer?(fn: () => void, ms: number): unknown;
  clearTimer?(handle: unknown): void;
}

export interface ConferenceInviteOverlay {
  root: HTMLElement;
  conferenceId: string;
  focus(): void;
  destroy(reason?: ConferenceInviteCloseReason): void;
}

const TEXT = {
  ru: {
    audioTitle: "Приглашение в аудиозвонок",
    videoTitle: "Приглашение в видеозвонок",
    lead: "{name} приглашает вас присоединиться",
    unknown: "Участник",
    decline: "Отклонить",
    join: "Войти",
    joining: "Подключаем…",
    failed: "Не удалось подключиться. Попробуйте ещё раз.",
  },
  en: {
    audioTitle: "Audio call invitation",
    videoTitle: "Video call invitation",
    lead: "{name} invited you to join",
    unknown: "A participant",
    decline: "Decline",
    join: "Join",
    joining: "Joining…",
    failed: "Could not join. Try again.",
  },
} as const;

export function createConferenceInviteOverlay(deps: ConferenceInviteOverlayDeps): ConferenceInviteOverlay {
  const text = deps.locale.toLowerCase().startsWith("ru") ? TEXT.ru : TEXT.en;
  const name = deps.notice.inviterName || text.unknown;
  const root = el("section", {
    class: "gc-conference-incoming",
    role: "dialog",
    "aria-modal": "true",
    "aria-labelledby": "gc-conference-incoming-title",
    tabindex: "-1",
    "data-conference-id": deps.notice.conferenceId,
  });
  const trap = createFocusTrap(root);
  const avatar = el("div", {
    class: "gc-conference-incoming-avatar",
    "data-tone": String(avatarTone(name)),
    "aria-hidden": "true",
  }, [initials(name)]);
  const title = el("h2", { id: "gc-conference-incoming-title" }, [
    deps.notice.video ? text.videoTitle : text.audioTitle,
  ]);
  const lead = el("p", { class: "gc-conference-incoming-lead" }, [text.lead.replace("{name}", name)]);
  const status = el("p", {
    class: "gc-conference-incoming-status",
    role: "status",
    "aria-live": "polite",
    hidden: true,
  });
  const decline = el("button", { type: "button", class: "gc-conference-incoming-decline" }, [
    icon("close"), text.decline,
  ]);
  const accept = el("button", { type: "button", class: "gc-conference-incoming-accept" }, [
    icon(deps.notice.video ? "video" : "phone"), text.join,
  ]);
  root.append(
    el("div", { class: "gc-conference-incoming-card" }, [
      avatar,
      el("div", { class: "gc-conference-incoming-copy" }, [title, lead, status]),
      el("div", { class: "gc-conference-incoming-actions" }, [decline, accept]),
    ]),
  );

  let destroyed = false;
  let busy = false;
  let expiryTimer: unknown = null;
  const clearExpiry = (): void => {
    if (expiryTimer === null) return;
    if (deps.clearTimer) deps.clearTimer(expiryTimer);
    else clearTimeout(expiryTimer as ReturnType<typeof setTimeout>);
    expiryTimer = null;
  };
  const destroy = (reason: ConferenceInviteCloseReason = "replaced"): void => {
    if (destroyed) return;
    destroyed = true;
    clearExpiry();
    trap.release();
    root.remove();
    deps.onClosed?.(reason);
  };
  const declineInvite = (): void => {
    if (busy || destroyed) return;
    try { deps.onDecline?.(deps.notice); } finally { destroy("declined"); }
  };
  decline.addEventListener("click", declineInvite);
  root.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    declineInvite();
  });
  accept.addEventListener("click", () => {
    if (busy || destroyed) return;
    busy = true;
    accept.disabled = true;
    decline.disabled = true;
    status.hidden = false;
    status.textContent = text.joining;
    void Promise.resolve(deps.onAccept(deps.notice)).then(() => {
      destroy("accepted");
    }, () => {
      if (destroyed) return;
      busy = false;
      accept.disabled = false;
      decline.disabled = false;
      status.hidden = false;
      status.textContent = text.failed;
      accept.focus();
    });
  });

  if (deps.notice.expiresAt !== null) {
    const nowMs = deps.now ? deps.now() : Date.now();
    const delay = Math.max(0, deps.notice.expiresAt * 1000 - nowMs);
    const run = (): void => destroy("expired");
    expiryTimer = deps.setTimer ? deps.setTimer(run, delay) : setTimeout(run, delay);
  }

  return {
    root,
    conferenceId: deps.notice.conferenceId,
    focus: () => trap.activate(),
    destroy,
  };
}
