// Android-native update installer seam.
//
// Opening an APK URL in a browser is not a reliable update mechanism: some Android builds route the
// intent to a plain WebView that cannot download files. The native MediaFiles plugin therefore owns the
// transfer, streams the artifact directly to MediaStore, verifies its SHA-256 while writing, and opens
// the resulting content:// URI with the system package installer. The shared UI feature-detects that
// method through Capacitor.Plugins so web/PWA/iOS builds remain untouched.

export interface NativeUpdateArtifact {
  url: string;
  sha256: string | null;
  version?: string;
}

export interface NativeUpdateInstallResult {
  saved: boolean;
  opened: boolean;
  uri: string;
}

export interface NativeUpdateInstallerPlugin {
  downloadAndOpen(options: {
    url: string;
    name: string;
    mime: string;
    sha256: string;
  }): Promise<NativeUpdateInstallResult>;
}

export interface NativeUpdateInstallerEnv {
  plugin(): NativeUpdateInstallerPlugin | null;
}

const APK_MIME = "application/vnd.android.package-archive";
const SHA256_RE = /^[a-f0-9]{64}$/;
const SAFE_APK_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,180}\.apk$/i;

function artifactName(url: string, version?: string): string {
  try {
    const leaf = decodeURIComponent(new URL(url).pathname.split("/").pop() ?? "");
    if (SAFE_APK_NAME_RE.test(leaf)) return leaf;
  } catch {
    // The validity check below owns the final verdict; this only chooses a display name.
  }
  const safeVersion = String(version ?? "update").replace(/[^A-Za-z0-9._-]+/g, "-").slice(0, 80) || "update";
  return `GreenChat-${safeVersion}.apk`;
}

/**
 * Returns false when this shell has no native installer capability. A present capability either opens
 * the package installer (true) or rejects: callers must keep the update surface available for retry.
 */
export async function installNativeUpdate(
  artifact: NativeUpdateArtifact,
  env: NativeUpdateInstallerEnv = browserNativeUpdateInstallerEnv(),
): Promise<boolean> {
  const sha256 = String(artifact.sha256 ?? "").trim().toLowerCase();
  if (!SHA256_RE.test(sha256)) return false;

  let url: URL;
  try {
    url = new URL(artifact.url);
  } catch {
    return false;
  }
  if (url.protocol !== "https:") return false;

  const plugin = env.plugin();
  if (!plugin || typeof plugin.downloadAndOpen !== "function") return false;
  const result = await plugin.downloadAndOpen({
    url: url.href,
    name: artifactName(url.href, artifact.version),
    mime: APK_MIME,
    sha256,
  });
  if (!result?.saved || !result.opened || !result.uri) throw new Error("NATIVE_UPDATE_INSTALLER_NOT_OPENED");
  return true;
}

export function browserNativeUpdateInstallerEnv(): NativeUpdateInstallerEnv {
  return {
    plugin: () => {
      const shell = globalThis as typeof globalThis & {
        Capacitor?: {
          getPlatform?: () => string;
          Plugins?: { MediaFiles?: Partial<NativeUpdateInstallerPlugin> };
        };
      };
      if (shell.Capacitor?.getPlatform?.() !== "android") return null;
      const media = shell.Capacitor.Plugins?.MediaFiles;
      return media && typeof media.downloadAndOpen === "function"
        ? media as NativeUpdateInstallerPlugin
        : null;
    },
  };
}
