// clients/web/src/session_storage.ts — protected multi-account session catalogue (GreenChat v223).
// Access tokens remain memory-only. Up to ten rotating refresh sessions plus tiny user snapshots are stored
// under the existing single `gc.session` key, so Android Keystore / desktop Keychain bridges keep protecting
// the complete catalogue without exposing per-account secrets to ordinary localStorage.
import {
  AccountLimitError,
  MAX_LOCAL_ACCOUNTS,
  type MultiAccountSessionStorage,
  type PersistedSession,
} from "../../ui/src/screens/session.ts";

export interface WebSessionStorageArea {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

interface PersistedAccountCatalog {
  version: 1;
  active_user_id: number | null;
  accounts: PersistedSession[];
}

type SessionPersistenceGlobal = typeof globalThis & {
  __gcFlushSessionStorage?: () => Promise<void>;
};

async function flushSessionStorage(): Promise<void> {
  const flush = (globalThis as SessionPersistenceGlobal).__gcFlushSessionStorage;
  if (typeof flush === "function") await flush();
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function cloneSession(value: PersistedSession): PersistedSession {
  return {
    refresh: value.refresh,
    ...(value.pendingRefresh ? { pendingRefresh: value.pendingRefresh } : {}),
    user: { ...value.user },
  };
}

function parseSessionValue(parsed: unknown): PersistedSession | null {
  if (!isRecord(parsed)) return null;
  if (typeof parsed.refresh !== "string" || parsed.refresh.length === 0 || parsed.refresh.length > 4096) return null;
  const pendingRefresh = parsed.pendingRefresh;
  if (
    pendingRefresh !== undefined &&
    (typeof pendingRefresh !== "string" || !/^[0-9a-f]{96}$/.test(pendingRefresh) || pendingRefresh === parsed.refresh)
  ) return null;
  if (!isRecord(parsed.user)) return null;
  const { id, username, name, avatar_file_id: rawAvatarFileId } = parsed.user;
  if (!Number.isSafeInteger(id) || Number(id) <= 0) return null;
  if (typeof username !== "string" || username.length === 0 || username.length > 128) return null;
  if (typeof name !== "string" || name.length > 512) return null;
  if (
    rawAvatarFileId !== undefined &&
    rawAvatarFileId !== null &&
    (!Number.isSafeInteger(rawAvatarFileId) || Number(rawAvatarFileId) <= 0)
  ) return null;
  const avatarFileId = rawAvatarFileId === null ? null : Number(rawAvatarFileId);
  return {
    refresh: parsed.refresh,
    ...(typeof pendingRefresh === "string" ? { pendingRefresh } : {}),
    user: {
      id: Number(id),
      username,
      name,
      ...(rawAvatarFileId === undefined ? {} : { avatar_file_id: avatarFileId }),
    },
  };
}

/** Parse the legacy/single-account persisted slice. Kept as a public validation contract for tests. */
export function parsePersistedSession(raw: string): PersistedSession | null {
  try { return parseSessionValue(JSON.parse(raw)); } catch { return null; }
}

function emptyCatalog(): PersistedAccountCatalog {
  return { version: 1, active_user_id: null, accounts: [] };
}

function parseCatalog(raw: string): PersistedAccountCatalog | null {
  let parsed: unknown;
  try { parsed = JSON.parse(raw); } catch { return null; }

  // Seamless migration from the original `{refresh,user}` value.
  const legacy = parseSessionValue(parsed);
  if (legacy) {
    return { version: 1, active_user_id: legacy.user.id, accounts: [legacy] };
  }
  if (!isRecord(parsed) || parsed.version !== 1 || !Array.isArray(parsed.accounts)) return null;
  if (parsed.accounts.length > MAX_LOCAL_ACCOUNTS) return null;

  const accounts: PersistedSession[] = [];
  const ids = new Set<number>();
  for (const item of parsed.accounts) {
    const session = parseSessionValue(item);
    if (!session || ids.has(session.user.id)) return null;
    ids.add(session.user.id);
    accounts.push(session);
  }
  const active = parsed.active_user_id;
  if (active !== null && (!Number.isSafeInteger(active) || !ids.has(Number(active)))) return null;
  return { version: 1, active_user_id: active === null ? null : Number(active), accounts };
}

export function webSessionStorage(
  key = "gc.session",
  storageOverride?: WebSessionStorageArea,
): MultiAccountSessionStorage {
  const area = storageOverride ?? (() => {
    try { return typeof localStorage !== "undefined" ? localStorage : undefined; }
    catch { return undefined; }
  })();
  let memory = emptyCatalog();

  const removeCorrupt = (): void => {
    memory = emptyCatalog();
    try { area?.removeItem(key); } catch { /* storage may be blocked */ }
  };

  const readCatalog = (): PersistedAccountCatalog => {
    if (!area) return memory;
    try {
      const raw = area.getItem(key);
      if (!raw) return memory;
      const parsed = parseCatalog(raw);
      if (!parsed) {
        removeCorrupt();
        return memory;
      }
      memory = parsed;
      return parsed;
    } catch {
      return memory;
    }
  };

  const writeCatalog = (catalog: PersistedAccountCatalog): void => {
    memory = {
      version: 1,
      active_user_id: catalog.active_user_id,
      accounts: catalog.accounts.map(cloneSession),
    };
    try { area?.setItem(key, JSON.stringify(memory)); } catch { /* quota / privacy mode */ }
  };

  return {
    load(): PersistedSession | null {
      const catalog = readCatalog();
      if (catalog.active_user_id === null) return null;
      const value = catalog.accounts.find((entry) => entry.user.id === catalog.active_user_id);
      return value ? cloneSession(value) : null;
    },
    save(value: PersistedSession): void {
      const catalog = readCatalog();
      const index = catalog.accounts.findIndex((entry) => entry.user.id === value.user.id);
      if (index < 0 && catalog.accounts.length >= MAX_LOCAL_ACCOUNTS) throw new AccountLimitError();
      const accounts = catalog.accounts.map(cloneSession);
      if (index >= 0) accounts[index] = cloneSession(value);
      else accounts.push(cloneSession(value));
      // A stale background tab may rotate another retained account. It may update that account's token,
      // but only an explicit selector (or a suspended add-account flow) may change the active identity.
      const active = catalog.active_user_id === null || catalog.active_user_id === value.user.id
        ? value.user.id
        : catalog.active_user_id;
      writeCatalog({ version: 1, active_user_id: active, accounts });
    },
    clear(): void {
      removeCorrupt();
    },
    flush: flushSessionStorage,
    listAccounts(): readonly PersistedSession[] {
      return readCatalog().accounts.map(cloneSession);
    },
    activeUserId(): number | null {
      return readCatalog().active_user_id;
    },
    selectAccount(userId: number): PersistedSession | null {
      const catalog = readCatalog();
      const value = catalog.accounts.find((entry) => entry.user.id === userId);
      if (!value) return null;
      writeCatalog({ ...catalog, active_user_id: userId });
      return cloneSession(value);
    },
    suspendActive(): void {
      const catalog = readCatalog();
      if (catalog.active_user_id !== null) writeCatalog({ ...catalog, active_user_id: null });
    },
    removeAccount(userId: number): void {
      const catalog = readCatalog();
      const accounts = catalog.accounts.filter((entry) => entry.user.id !== userId);
      if (accounts.length === catalog.accounts.length) return;
      writeCatalog({
        version: 1,
        active_user_id: catalog.active_user_id === userId ? null : catalog.active_user_id,
        accounts,
      });
    },
    updateAccountAvatar(userId: number, avatarFileId: number | null): void {
      if (!Number.isSafeInteger(userId) || userId <= 0) return;
      if (avatarFileId !== null && (!Number.isSafeInteger(avatarFileId) || avatarFileId <= 0)) return;
      const catalog = readCatalog();
      const index = catalog.accounts.findIndex((entry) => entry.user.id === userId);
      if (index < 0) return;
      const accounts = catalog.accounts.map(cloneSession);
      const current = accounts[index]!;
      accounts[index] = {
        ...current,
        user: { ...current.user, avatar_file_id: avatarFileId },
      };
      writeCatalog({ ...catalog, accounts });
    },
  };
}
