// The only audited gateway allowed to place sensitive one-time values in the system clipboard.
// Callers must invoke it from an explicit user action and must never log, persist or analyse `value`.

export interface SensitiveCopyEnvironment {
  writeText?: (value: string) => Promise<void>;
  legacyCopy?: (value: string) => boolean;
}

function legacyDocumentCopy(value: string): boolean {
  if (typeof document === "undefined" || !document.body || typeof document.execCommand !== "function") {
    return false;
  }

  const field = document.createElement("textarea");
  field.value = value;
  field.setAttribute("readonly", "");
  field.setAttribute("aria-hidden", "true");
  field.style.position = "fixed";
  field.style.inset = "-10000px auto auto -10000px";
  field.style.width = "1px";
  field.style.height = "1px";
  field.style.opacity = "0";
  field.style.pointerEvents = "none";
  document.body.append(field);

  try {
    field.select();
    field.setSelectionRange(0, value.length);
    return document.execCommand("copy");
  } finally {
    field.value = "";
    field.remove();
  }
}

function browserEnvironment(): SensitiveCopyEnvironment {
  const clipboard = typeof navigator !== "undefined" ? navigator.clipboard : undefined;
  const environment: SensitiveCopyEnvironment = { legacyCopy: legacyDocumentCopy };
  if (clipboard?.writeText) environment.writeText = clipboard.writeText.bind(clipboard);
  return environment;
}

/** Copy a sensitive value without reading the clipboard or retaining a second copy in app state. */
export async function copySensitiveText(
  value: string,
  environment: SensitiveCopyEnvironment = browserEnvironment(),
): Promise<"clipboard" | "legacy"> {
  if (!value) throw new Error("SENSITIVE_COPY_EMPTY");

  if (environment.writeText) {
    try {
      await environment.writeText(value);
      return "clipboard";
    } catch {
      // Older Android WebViews may expose the API but reject it; use the synchronous user-gesture fallback.
    }
  }

  if (environment.legacyCopy?.(value)) return "legacy";
  throw new Error("SENSITIVE_COPY_FAILED");
}
