// Full-screen profile-photo history viewer. Newest/current photo opens first; users can page or swipe
// through older avatars, like each photo idempotently, and the owner can remove photos from history.
import type { I18n, Locale } from "../i18n.ts";
import { clear, el } from "../dom.ts";
import { createFocusTrap } from "../a11y.ts";
import { icon } from "../icons.ts";
import type { ApiLike } from "./api.ts";
import { describeError } from "./api.ts";
import { avatarTone, initials } from "./message_menu.ts";
import { bindAvatarImage, type AvatarImageBinding } from "./avatar_media.ts";

export interface ProfilePhoto {
  id: number;
  file_id: number;
  created_at: number;
  likes: number;
  liked_by_me: boolean;
  is_current: boolean;
}

interface LikeResult {
  photo_id: number;
  likes: number;
  liked_by_me: boolean;
}

interface DeleteResult {
  deleted: true;
  avatar_file_id: number | null;
}

type GalleryApi = Pick<ApiLike, "get" | "put" | "delete" | "resolveUrl">;

export interface ProfilePhotoGalleryDeps {
  api: GalleryApi;
  i18n: I18n;
  userId: number;
  title: string;
  isOwner?: boolean;
  onCurrentChanged?(fileId: number | null): void;
}

export interface ProfilePhotoGallery {
  root: HTMLElement;
  open(preferredFileId?: number | null): Promise<void>;
  close(): void;
  refresh(preferredFileId?: number | null): Promise<void>;
  destroy(): void;
}

type CopyKey =
  | "title" | "loading" | "empty" | "close" | "previous" | "next" | "counter"
  | "like" | "unlike" | "delete" | "current" | "loadFailed";

const COPY: Record<Locale, Record<CopyKey, string>> = {
  ru: {
    title: "Фото профиля",
    loading: "Загружаем фотографии…",
    empty: "Фотографий профиля пока нет",
    close: "Закрыть галерею",
    previous: "Предыдущее фото",
    next: "Следующее фото",
    counter: "{current} из {total}",
    like: "Поставить лайк",
    unlike: "Убрать лайк",
    delete: "Удалить это фото",
    current: "Главное фото",
    loadFailed: "Не удалось загрузить фотографии",
  },
  en: {
    title: "Profile photos",
    loading: "Loading photos…",
    empty: "No profile photos yet",
    close: "Close gallery",
    previous: "Previous photo",
    next: "Next photo",
    counter: "{current} of {total}",
    like: "Like photo",
    unlike: "Remove like",
    delete: "Delete this photo",
    current: "Main photo",
    loadFailed: "Could not load photos",
  },
};

function validPhoto(value: unknown): value is ProfilePhoto {
  if (!value || typeof value !== "object") return false;
  const row = value as Partial<ProfilePhoto>;
  return Number.isSafeInteger(Number(row.id)) && Number(row.id) > 0
    && Number.isSafeInteger(Number(row.file_id)) && Number(row.file_id) > 0
    && Number.isFinite(Number(row.created_at))
    && Number.isFinite(Number(row.likes)) && Number(row.likes) >= 0
    && typeof row.liked_by_me === "boolean"
    && typeof row.is_current === "boolean";
}

export function createProfilePhotoGallery(deps: ProfilePhotoGalleryDeps): ProfilePhotoGallery {
  const { api, i18n } = deps;
  const t = (key: CopyKey, params?: Record<string, string | number>): string => {
    const template = COPY[i18n.locale][key];
    if (!params) return template;
    return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
      params[name] === undefined ? whole : String(params[name]));
  };

  let photos: ProfilePhoto[] = [];
  let index = 0;
  let opened = false;
  let destroyed = false;
  let loading = false;
  let loadFailure: string | null = null;
  let epoch = 0;
  let imageBinding: AvatarImageBinding | null = null;
  let swipeStartX: number | null = null;

  const closeButton = el("button", {
    type: "button",
    class: "gc-icon-btn gc-profile-photo-close",
    title: t("close"),
    "aria-label": t("close"),
  }, [icon("close")]) as HTMLButtonElement;
  const heading = el("strong", { class: "gc-profile-photo-title" }, [t("title")]);
  const status = el("p", {
    class: "gc-profile-photo-status",
    role: "status",
    "aria-live": "polite",
  });
  const stage = el("div", {
    class: "gc-profile-photo-stage",
    "data-tone": String(avatarTone(deps.title)),
  });
  const prev = el("button", {
    type: "button",
    class: "gc-profile-photo-nav is-prev",
    title: t("previous"),
    "aria-label": t("previous"),
  }, [icon("chevron")]) as HTMLButtonElement;
  const next = el("button", {
    type: "button",
    class: "gc-profile-photo-nav is-next",
    title: t("next"),
    "aria-label": t("next"),
  }, [icon("chevron")]) as HTMLButtonElement;
  const counter = el("span", { class: "gc-profile-photo-counter" });
  const currentBadge = el("span", { class: "gc-profile-photo-current" }, [t("current")]);
  const likeButton = el("button", {
    type: "button",
    class: "gc-profile-photo-like",
  }) as HTMLButtonElement;
  const deleteButton = el("button", {
    type: "button",
    class: "gc-profile-photo-delete",
    title: t("delete"),
    "aria-label": t("delete"),
  }, [icon("trash")]) as HTMLButtonElement;
  const dots = el("div", { class: "gc-profile-photo-dots", "aria-hidden": "true" });
  const footer = el("div", { class: "gc-profile-photo-footer" }, [
    el("div", { class: "gc-profile-photo-meta" }, [counter, currentBadge]),
    dots,
    el("div", { class: "gc-profile-photo-actions" }, [likeButton, ...(deps.isOwner ? [deleteButton] : [])]),
  ]);
  const panel = el("div", {
    class: "gc-profile-photo-panel",
    role: "dialog",
    "aria-modal": "true",
    "aria-label": t("title"),
  }, [
    el("div", { class: "gc-profile-photo-bar" }, [heading, closeButton]),
    el("div", { class: "gc-profile-photo-canvas" }, [prev, stage, next]),
    status,
    footer,
  ]);
  const root = el("div", { class: "gc-profile-photo-viewer", hidden: true }, [panel]);
  const trap = createFocusTrap(panel, { initialFocus: closeButton });

  const current = (): ProfilePhoto | null => photos[index] ?? null;

  const paintMeta = (): void => {
    const photo = current();
    const multiple = photos.length > 1;
    prev.hidden = !multiple;
    next.hidden = !multiple;
    footer.hidden = !photo;
    if (!photo) return;
    counter.textContent = t("counter", { current: index + 1, total: photos.length });
    currentBadge.hidden = !photo.is_current;
    likeButton.classList.toggle("is-liked", photo.liked_by_me);
    likeButton.setAttribute("aria-pressed", String(photo.liked_by_me));
    likeButton.setAttribute("aria-label", t(photo.liked_by_me ? "unlike" : "like"));
    likeButton.title = t(photo.liked_by_me ? "unlike" : "like");
    likeButton.replaceChildren(
      el("span", { class: "gc-profile-photo-heart", "aria-hidden": "true" }, [photo.liked_by_me ? "♥" : "♡"]),
      el("span", { class: "gc-profile-photo-like-count" }, [String(photo.likes)]),
    );
    clear(dots);
    if (photos.length <= 12) {
      dots.append(...photos.map((_row, at) => el("span", {
        class: `gc-profile-photo-dot${at === index ? " is-active" : ""}`,
      })));
    }
  };

  const paintPhoto = (): void => {
    imageBinding?.destroy();
    imageBinding = null;
    clear(stage);
    const photo = current();
    if (!photo) {
      stage.append(el("span", { class: "gc-profile-photo-empty-mark", "aria-hidden": "true" }, [initials(deps.title)]));
      status.textContent = loading ? t("loading") : (loadFailure ?? t("empty"));
      status.hidden = false;
      paintMeta();
      return;
    }
    status.textContent = "";
    status.hidden = true;
    stage.append(el("span", { class: "gc-profile-photo-empty-mark", "aria-hidden": "true" }, [initials(deps.title)]));
    imageBinding = bindAvatarImage(stage, api, photo.file_id, deps.title);
    paintMeta();
  };

  const select = (delta: number): void => {
    if (photos.length < 2) return;
    index = (index + delta + photos.length) % photos.length;
    paintPhoto();
  };

  const load = async (preferredFileId?: number | null): Promise<void> => {
    const run = ++epoch;
    loadFailure = null;
    loading = true;
    paintPhoto();
    try {
      const result = await api.get<unknown>(`/v1/users/${deps.userId}/photos`);
      if (destroyed || run !== epoch) return;
      photos = Array.isArray(result) ? result.filter(validPhoto) : [];
      const preferred = typeof preferredFileId === "number"
        ? photos.findIndex((photo) => photo.file_id === preferredFileId)
        : -1;
      const main = photos.findIndex((photo) => photo.is_current);
      index = preferred >= 0 ? preferred : main >= 0 ? main : 0;
    } catch (error) {
      if (destroyed || run !== epoch) return;
      photos = [];
      loadFailure = `${t("loadFailed")}: ${describeError(error, i18n)}`;
    } finally {
      if (!destroyed && run === epoch) {
        loading = false;
        paintPhoto();
      }
    }
  };

  const toggleLike = async (): Promise<void> => {
    const photo = current();
    if (!photo || likeButton.disabled) return;
    const wanted = !photo.liked_by_me;
    const oldLikes = photo.likes;
    const oldMine = photo.liked_by_me;
    photo.liked_by_me = wanted;
    photo.likes = Math.max(0, oldLikes + (wanted ? 1 : -1));
    likeButton.disabled = true;
    paintMeta();
    try {
      const saved = await api.put<LikeResult>(
        `/v1/users/${deps.userId}/photos/${photo.id}/like`,
        { liked: wanted },
      );
      if (destroyed) return;
      const live = photos.find((row) => row.id === saved.photo_id);
      if (live) {
        live.likes = saved.likes;
        live.liked_by_me = saved.liked_by_me;
      }
    } catch (error) {
      photo.likes = oldLikes;
      photo.liked_by_me = oldMine;
      status.textContent = describeError(error, i18n);
      status.hidden = false;
    } finally {
      if (!destroyed) {
        likeButton.disabled = false;
        paintMeta();
      }
    }
  };

  const removeCurrent = async (): Promise<void> => {
    const photo = current();
    if (!deps.isOwner || !photo || deleteButton.disabled) return;
    deleteButton.disabled = true;
    try {
      const result = await api.delete<DeleteResult>(`/v1/users/me/photos/${photo.id}`);
      if (destroyed) return;
      photos = photos.filter((row) => row.id !== photo.id);
      for (const row of photos) row.is_current = row.file_id === result.avatar_file_id;
      if (index >= photos.length) index = Math.max(0, photos.length - 1);
      deps.onCurrentChanged?.(result.avatar_file_id);
      paintPhoto();
    } catch (error) {
      status.textContent = describeError(error, i18n);
      status.hidden = false;
    } finally {
      if (!destroyed) deleteButton.disabled = false;
    }
  };

  const close = (): void => {
    if (!opened) return;
    opened = false;
    root.hidden = true;
    trap.release();
  };

  closeButton.addEventListener("click", close);
  prev.addEventListener("click", () => select(-1));
  next.addEventListener("click", () => select(1));
  likeButton.addEventListener("click", () => { void toggleLike(); });
  deleteButton.addEventListener("click", () => { void removeCurrent(); });
  root.addEventListener("click", (event) => { if (event.target === root) close(); });
  root.addEventListener("keydown", (event) => {
    const key = (event as KeyboardEvent).key;
    if (key === "Escape") { event.stopPropagation(); close(); }
    else if (key === "ArrowLeft") { event.preventDefault(); select(-1); }
    else if (key === "ArrowRight") { event.preventDefault(); select(1); }
  });
  stage.addEventListener("pointerdown", (event) => {
    const x = Number((event as PointerEvent).clientX);
    swipeStartX = Number.isFinite(x) ? x : null;
  });
  stage.addEventListener("pointerup", (event) => {
    if (swipeStartX === null) return;
    const x = Number((event as PointerEvent).clientX);
    const delta = Number.isFinite(x) ? x - swipeStartX : 0;
    swipeStartX = null;
    if (Math.abs(delta) >= 42) select(delta > 0 ? -1 : 1);
  });
  stage.addEventListener("pointercancel", () => { swipeStartX = null; });

  return {
    root,
    async open(preferredFileId?: number | null): Promise<void> {
      if (destroyed) return;
      opened = true;
      root.hidden = false;
      trap.activate();
      await load(preferredFileId);
    },
    close,
    refresh: load,
    destroy() {
      if (destroyed) return;
      close();
      destroyed = true;
      epoch += 1;
      imageBinding?.destroy();
      imageBinding = null;
      root.remove();
    },
  };
}
