// Lightweight auth entry. The full form is loaded only for signed-out users, keeping the authenticated
// application shell inside its initial-transfer budget without changing the public screen contract.
import type { AuthScreenDeps } from "./auth_screen_impl.ts";

export type { AuthScreenDeps, RegistrationMode, RegistrationModePort } from "./auth_screen_impl.ts";

type MountedAuth = { root: HTMLElement; destroy(): void };

export function createAuthScreen(deps: AuthScreenDeps): MountedAuth {
  const root = document.createElement("div");
  root.setAttribute("class", "gc-auth gc-auth-loading");
  root.setAttribute("aria-busy", "true");
  let disposed = false;
  let mounted: MountedAuth | null = null;

  void import("./auth_screen_impl.ts").then((module) => {
    if (disposed) return;
    mounted = module.createAuthScreen(deps);
    root.removeAttribute("aria-busy");
    root.setAttribute("class", "gc-auth-loader-host");
    while (root.firstChild) root.removeChild(root.firstChild);
    root.append(mounted.root);
  }).catch(() => {
    if (!disposed) root.setAttribute("data-load-error", "true");
  });

  return {
    root,
    destroy() {
      disposed = true;
      mounted?.destroy();
    },
  };
}
