export interface ConferenceInviteNotice {
  conferenceId: string;
  chatId: number;
  inviterId: number | null;
  inviterName: string;
  video: boolean;
  expiresAt: number | null;
}

function object(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function positiveInt(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : null;
}

export function conferenceEventId(payload: unknown): string | null {
  const body = object(payload);
  const room = object(body?.conference);
  const value = body?.conference_id ?? room?.id;
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

/** Parse only a live, targeted conference invitation. Malformed/expired durable events stay invisible. */
export function conferenceInviteFromEvent(
  type: string,
  payload: unknown,
  nowSec = Math.floor(Date.now() / 1000),
): ConferenceInviteNotice | null {
  if (type !== "conference.invited") return null;
  const body = object(payload);
  const room = object(body?.conference);
  if (!body || !room) return null;
  const conferenceId = conferenceEventId(body);
  const chatId = positiveInt(room.chat_id ?? body.chat_id);
  if (!conferenceId || chatId === null) return null;

  const expiresRaw = body.expires_at;
  const expiresAt = expiresRaw === undefined || expiresRaw === null ? null : positiveInt(expiresRaw);
  if (expiresRaw !== undefined && expiresRaw !== null && expiresAt === null) return null;
  if (expiresAt !== null && expiresAt <= nowSec) return null;

  const inviter = object(body.inviter);
  const inviterId = positiveInt(inviter?.id);
  const inviterName = typeof inviter?.name === "string" ? inviter.name.trim() : "";
  return {
    conferenceId,
    chatId,
    inviterId,
    inviterName,
    video: room.video === true,
    expiresAt,
  };
}
