// Cross-browser QR decoder. Chromium's BarcodeDetector is fast when present, while jsQR keeps the
// camera scanner working in Firefox, Safari and Android WebViews that expose getUserMedia but not the
// experimental detector API. The compatibility decoder is loaded only on first use, so the 140 KB
// implementation never inflates GreenChat's initial route bundle.

type BarcodeResult = { rawValue?: string };
type BarcodeDetectorLike = { detect(source: unknown): Promise<BarcodeResult[]> };
type BarcodeDetectorCtor = new (opts?: { formats?: string[] }) => BarcodeDetectorLike;
type JsQrDecoder = typeof import("../vendor/jsqr.js").default;
let jsQrPromise: Promise<JsQrDecoder> | null = null;
const loadJsQr = (): Promise<JsQrDecoder> => {
  jsQrPromise ??= import("../vendor/jsqr.js").then((module) => module.default);
  return jsQrPromise;
};

export interface QrFrameDecoder {
  decode(video: HTMLVideoElement): Promise<string | null>;
}

export interface QrFrameDecoderOptions {
  /** Test/native seam. Omitted means feature-detect the browser implementation. */
  detector?: BarcodeDetectorLike | null;
  /** A partial Android WebView detector must never freeze the scanner indefinitely. */
  detectorTimeoutMs?: number;
  /** Test seam for the canvas/jsQR compatibility path. */
  decodePixels?: (video: HTMLVideoElement) => Promise<string | null>;
}

function detectorCtor(): BarcodeDetectorCtor | null {
  const ctor = (globalThis as { BarcodeDetector?: BarcodeDetectorCtor }).BarcodeDetector;
  return typeof ctor === "function" ? ctor : null;
}

function detectWithin(
  detector: BarcodeDetectorLike,
  source: HTMLVideoElement,
  timeoutMs: number,
): Promise<BarcodeResult[] | null> {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value: BarcodeResult[] | null): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(value);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    try {
      void Promise.resolve(detector.detect(source)).then(
        (rows) => finish(Array.isArray(rows) ? rows : []),
        () => finish(null),
      );
    } catch {
      finish(null);
    }
  });
}

export function createQrFrameDecoder(
  doc: Pick<Document, "createElement"> = document,
  options: QrFrameDecoderOptions = {},
): QrFrameDecoder {
  const Detector = detectorCtor();
  let detector = Object.prototype.hasOwnProperty.call(options, "detector")
    ? options.detector ?? null
    : Detector ? new Detector({ formats: ["qr_code"] }) : null;
  const detectorTimeoutMs = Math.max(16, Math.floor(options.detectorTimeoutMs ?? 160));
  let canvas: HTMLCanvasElement | null = null;
  let context: CanvasRenderingContext2D | null = null;

  const decodePixels = options.decodePixels ?? (async (video: HTMLVideoElement): Promise<string | null> => {
    const sourceWidth = Math.floor(video.videoWidth || 0);
    const sourceHeight = Math.floor(video.videoHeight || 0);
    if (sourceWidth < 2 || sourceHeight < 2) return null;
    const maxWidth = 960;
    const scale = Math.min(1, maxWidth / sourceWidth);
    const width = Math.max(2, Math.round(sourceWidth * scale));
    const height = Math.max(2, Math.round(sourceHeight * scale));
    canvas ??= doc.createElement("canvas");
    if (!context) context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return null;
    if (canvas.width !== width) canvas.width = width;
    if (canvas.height !== height) canvas.height = height;
    context.drawImage(video, 0, 0, width, height);
    const image = context.getImageData(0, 0, width, height);
    const jsQr = await loadJsQr();
    return jsQr(image.data, width, height, { inversionAttempts: "attemptBoth" })?.data ?? null;
  });

  return {
    async decode(video) {
      if (detector) {
        const rows = await detectWithin(detector, video, detectorTimeoutMs);
        if (rows === null) {
          // Some Android WebViews expose BarcodeDetector but never settle detect(video). One bounded
          // attempt is enough: permanently move this scanner to jsQR instead of freezing every frame.
          detector = null;
        } else {
          const value = rows.find((row) => typeof row.rawValue === "string" && row.rawValue.length > 0)?.rawValue;
          if (value) return value;
        }
      }
      try {
        return await decodePixels(video);
      } catch {
        // Video can be between frames while a camera switches; the caller retries on its normal tick.
        return null;
      }
    },
  };
}
